insert into public.destinations (slug, name, region, category_slug, environment, lat, lng, tagline, summary, interests, min_budget_level, ideal_days, best_months, hidden_gem, photo_key, passport_fact) values ('nubia', 'Nubian villages', 'Upper Egypt', 'nature', 'river', 24.1, 32.87, 'Painted houses and Nubian hospitality', 'On the west bank of Aswan, Nubian communities welcome visitors to guesthouses, home kitchens and crafts. Book with community-run hosts where possible.', '{"culture":3,"family":2,"food":2,"photography":2,"relaxation":2}'::jsonb, 1, int4range(1, 2, '[]'), array[11,12,1,2]::smallint[], true, 'nubian', 'Nubian is a family of languages spoken along the Nile in southern Egypt and Sudan.') on conflict (slug) do update set name = excluded.name, tagline = excluded.tagline, summary = excluded.summary, interests = excluded.interests, best_months = excluded.best_months;
